import{_ as t,c as a,o as i,a2 as n}from"./chunks/framework.mqLGQ42V.js";const m=JSON.parse('{"title":"IK 约束 (IK Constraint) - Rive 编辑器","description":"约束 (Constraints) 学习如何在 Rive 中使用反向动力学 (Inverse Kinematics)。","frontmatter":{"title":"IK 约束 (IK Constraint) - Rive 编辑器","description":"约束 (Constraints) 学习如何在 Rive 中使用反向动力学 (Inverse Kinematics)。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 约束, IK 约束"}]]},"headers":[],"relativePath":"editor/constraints/ik-constraint.md","filePath":"editor/constraints/ik-constraint.md","lastUpdated":1774867914000}'),r={name:"editor/constraints/ik-constraint.md"};function o(s,e,c,d,h,l){return i(),a("div",null,[...e[0]||(e[0]=[n('<p>约束 (Constraints)</p><h1 id="ik-约束-ik-constraint" tabindex="-1">IK 约束 (IK Constraint) <a class="header-anchor" href="#ik-约束-ik-constraint" aria-label="Permalink to &quot;IK 约束 (IK Constraint)&quot;">​</a></h1><p>学习如何在 Rive 中使用反向动力学 (Inverse Kinematics)。</p><h2 id="​-关于反向动力学-ik" tabindex="-1"><a href="#about-inverse-kinematics-ik">​</a> 关于反向动力学 (IK) <a class="header-anchor" href="#​-关于反向动力学-ik" aria-label="Permalink to &quot;[​](#about-inverse-kinematics-ik) 关于反向动力学 (IK)&quot;">​</a></h2><h3 id="​-正向动力学-forward-kinematics" tabindex="-1"><a href="#forward-kinematics">​</a> 正向动力学 (Forward Kinematics) <a class="header-anchor" href="#​-正向动力学-forward-kinematics" aria-label="Permalink to &quot;[​](#forward-kinematics) 正向动力学 (Forward Kinematics)&quot;">​</a></h3><p>Rive 中的大部分骨骼动画通过旋转骨骼的角度来完成。子级骨骼的位置会随着父级骨骼的旋转而变化。要让链条末端的骨骼到达特定位置，需要依次旋转多个父级骨骼。这种模式称为&quot;正向动力学&quot;。</p><h3 id="​-反向动力学-inverse-kinematics" tabindex="-1"><a href="#inverse-kinematics">​</a> 反向动力学 (Inverse Kinematics) <a class="header-anchor" href="#​-反向动力学-inverse-kinematics" aria-label="Permalink to &quot;[​](#inverse-kinematics) 反向动力学 (Inverse Kinematics)&quot;">​</a></h3><p>反向动力学允许你在骨骼链的末端放置一个目标点，系统会自动反推计算父级骨骼需要如何旋转才能使末端到达该目标。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: IK 示意图) 常见应用包括：让角色用手指向某个物体，或让角色的脚&quot;踩&quot;在地面上。</p></blockquote><h2 id="​-如何创建-ik-约束" tabindex="-1"><a href="#how-to-create-an-ik-constraint">​</a> 如何创建 IK 约束 <a class="header-anchor" href="#​-如何创建-ik-约束" aria-label="Permalink to &quot;[​](#how-to-create-an-ik-constraint) 如何创建 IK 约束&quot;">​</a></h2><p>使用 IK 需要一条骨骼链和一个目标对象。目标可以是任何对象，但通常使用 <a href="/docs/editor/fundamentals/groups#group-style">样式设为 Target 的分组</a>。</p><ol><li><strong>创建骨骼链和目标</strong>：按 <code>B</code> 创建<a href="/docs/editor/manipulating-shapes/bones">骨骼链</a>，按 <code>G</code> 创建一个<a href="/docs/editor/fundamentals/groups">分组</a>，并将分组样式设为 Target。</li><li><strong>添加 IK 约束</strong>：选中你希望受影响的最后一根骨骼，在检查器的 Constraints 部分添加 IK Constraint。</li><li><strong>选择目标</strong>：展开约束菜单，点击 Target 按钮选择步骤 1 中创建的空分组。</li><li><strong>测试 IK 系统</strong>：移动目标分组，观察骨骼链是否按预期跟随。</li></ol><h2 id="​-骨骼数量-bone-count" tabindex="-1"><a href="#bone-count">​</a> 骨骼数量 (Bone Count) <a class="header-anchor" href="#​-骨骼数量-bone-count" aria-label="Permalink to &quot;[​](#bone-count) 骨骼数量 (Bone Count)&quot;">​</a></h2><p>使用 Bone Count 属性设置 IK 系统向上影响多少根骨骼。当目标被选中时，受影响的骨骼会高亮显示。</p><h2 id="​-反转方向-invert-direction" tabindex="-1"><a href="#invert-direction">​</a> 反转方向 (Invert Direction) <a class="header-anchor" href="#​-反转方向-invert-direction" aria-label="Permalink to &quot;[​](#invert-direction) 反转方向 (Invert Direction)&quot;">​</a></h2><p>使用 Invert Direction 开关可以翻转 IK 系统求解的弯曲方向（例如：肘部向内弯还是向外弯）。</p><h2 id="​-强度-strength" tabindex="-1"><a href="#strength">​</a> 强度 (Strength) <a class="header-anchor" href="#​-强度-strength" aria-label="Permalink to &quot;[​](#strength) 强度 (Strength)&quot;">​</a></h2><p>Strength 属性控制受影响骨骼跟随目标的程度。0% 表示目标不影响骨骼。 <em>提示：Strength 可以设置动画，用于混合多个 IK 约束或创建独特效果。</em></p><h2 id="​-约束顺序" tabindex="-1"><a href="#constraints-order">​</a> 约束顺序 <a class="header-anchor" href="#​-约束顺序" aria-label="Permalink to &quot;[​](#constraints-order) 约束顺序&quot;">​</a></h2><p>约束的顺序很重要。例如，如果一根骨骼有两个 IK 约束且强度都是 100%，则最后添加的约束（最底部）会覆盖前一个。你可以拖放来调整约束顺序。</p><h2 id="​-多重-ik-约束与嵌套目标" tabindex="-1"><a href="#multiple-ik-constraints-and-nested-targets">​</a> 多重 IK 约束与嵌套目标 <a class="header-anchor" href="#​-多重-ik-约束与嵌套目标" aria-label="Permalink to &quot;[​](#multiple-ik-constraints-and-nested-targets) 多重 IK 约束与嵌套目标&quot;">​</a></h2><p>你可以为复杂的绑定设置多个 IK 约束。常见做法是为角色的脚设置一个 IK（影响 1 根骨骼），为腿部设置另一个 IK（影响 2 根骨骼）。腿部目标作为脚部目标的子级，这样移动脚就会带动腿。</p><p><a href="/docs/editor/constraints/overview">概览 (Overview)</a><a href="/docs/editor/constraints/distance-constraint">距离约束 (Distance Constraint)</a></p>',23)])])}const k=t(r,[["render",o]]);export{m as __pageData,k as default};
